mapper.update:
UPDATE proj_result_evidence_scan SET after_candidate_id=#{query.afterCandidateId},accumulator=#{query.accumulator},status=#{query.status},version=version+1
WHERE tenant_id=#{query.tenantId} AND project_id=#{query.projectId} AND id=#{query.id}
  AND version=#{query.expectedVersion} AND status='COLLECTING' AND after_candidate_id <= #{query.afterCandidateId}

mapper.select:
SELECT * FROM proj_result_evidence_scan WHERE tenant_id=#{query.tenantId} AND project_id=#{query.projectId}
  AND subscription_id=#{query.subscriptionId} AND subscription_version=#{query.subscriptionVersion}
ORDER BY id DESC LIMIT 1

SELECT DISTINCT reason FROM proj_result_evidence_item WHERE tenant_id=#{query.tenantId} AND project_id=#{query.projectId}
  AND scan_id=#{query.scanId} AND eligibility != 'ELIGIBLE' AND reason IS NOT NULL
ORDER BY reason LIMIT #{query.limit}
